    ratio: ['\\rho=\\frac{r_+}{r_-}:\\quad 0.225\\ (\\mathrm{CN}\\,4)\\ <\\ 0.414\\ (\\mathrm{CN}\\,6)\\ <\\ 0.732\\ (\\mathrm{CN}\\,8)', true],
